using System;using System.IO;using System.Diagnostics;using System.Drawing;using System.Windows.Forms;
class ServerPanel:Form {
 readonly string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"QuelliDelQuasiServer");
 readonly TextBox output=new TextBox();readonly ComboBox service=new ComboBox(),job=new ComboBox(),logs=new ComboBox();readonly FlowLayoutPanel tools=new FlowLayoutPanel();Process active;
 readonly string[] jobs={"results","odds","presence","lineups","derived","notifications"};readonly string[] logNames={"worker","web","caddy","postgres"};
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new ServerPanel());}
 ServerPanel(){Text="Quelli del Quasi · Sala macchine";Width=1100;Height=760;MinimumSize=new Size(760,540);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(12,25,21);ForeColor=Color.FromArgb(245,241,221);Font=new Font("Segoe UI",10);
  var title=new Label{Text="LA SALA MACCHINE DEL QUASI",Dock=DockStyle.Top,Height=50,Font=new Font("Segoe UI",18,FontStyle.Bold),Padding=new Padding(14,10,0,0)};Controls.Add(title);
  tools.Dock=DockStyle.Top;tools.Height=155;tools.Padding=new Padding(12);tools.AutoScroll=true;Controls.Add(tools);tools.BringToFront();
  Add("Stato",()=>Run("status"));service.DropDownStyle=ComboBoxStyle.DropDownList;service.Width=160;service.Items.AddRange(new object[]{"QuasiWeb","QuasiWorker","QuasiCaddy","QuasiPostgres"});service.SelectedIndex=0;tools.Controls.Add(service);
  Add("Avvia",()=>Service("start"));Add("Riavvia",()=>Service("restart"));Add("Ferma",()=>Service("stop"));Add("Backup",()=>{if(Confirm("Creare un backup locale consistente di DB e configurazione? Il sito resta attivo."))Run("backup");});
  tools.SetFlowBreak(tools.Controls[tools.Controls.Count-1],true);
  job.DropDownStyle=ComboBoxStyle.DropDownList;job.Width=310;job.Items.AddRange(new object[]{"Risultati dell’ultima giornata","Controlla le quote","Aggiorna stime di presenza","Verifica formazioni automatiche","Ricalcola risultati dai dati salvati","Invia notifiche pendenti"});job.SelectedIndex=0;tools.Controls.Add(job);
  Add("Lancia job",()=>{if(Confirm("Avviare il lavoro selezionato? Può aggiornare il DB, usare API o inviare notifiche. Esiti e metriche saranno visibili in Esiti job e Log worker."))Run("job "+jobs[job.SelectedIndex]);});Add("Esiti job",()=>Run("jobs"));Add("Test API",()=>{if(Confirm("Effettuare una chiamata API-Football per l’ultima partita e mostrare la risposta?"))Run("api-test");});
  tools.SetFlowBreak(tools.Controls[tools.Controls.Count-1],true);
  logs.DropDownStyle=ComboBoxStyle.DropDownList;logs.Width=160;logs.Items.AddRange(new object[]{"Worker e job","Server web","HTTPS / Caddy","PostgreSQL"});logs.SelectedIndex=0;tools.Controls.Add(logs);Add("Leggi log",()=>Run("logs "+logNames[logs.SelectedIndex]));Add("Apri sito",()=>Open("https://quellidelquasi.com"));Add("Admin dell’app",()=>Open("https://quellidelquasi.com/admin.html"));Add("Cartella server",()=>Open(root));
  var footer=new Label{Text="Controllo locale dei soli servizi Quasi. L’admin dell’app mantiene password e codice email. Nessun job parte aprendo il pannello.",Dock=DockStyle.Bottom,Height=45,Padding=new Padding(12,10,0,0)};Controls.Add(footer);
  output.Multiline=true;output.ReadOnly=true;output.ScrollBars=ScrollBars.Both;output.WordWrap=false;output.Dock=DockStyle.Fill;output.Font=new Font("Consolas",10);output.BackColor=Color.FromArgb(20,38,31);output.ForeColor=ForeColor;Controls.Add(output);output.BringToFront();tools.BringToFront();title.BringToFront();
  Controls.Clear();var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(0)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,160));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.Controls.Add(title,0,0);layout.Controls.Add(tools,0,1);layout.Controls.Add(output,0,2);layout.Controls.Add(footer,0,3);Controls.Add(layout);
  Shown+=(s,e)=>Run("status");FormClosing+=(s,e)=>{if(active!=null&&!active.HasExited&&!Confirm("Un comando è ancora in esecuzione. Chiudere il pannello senza interromperlo?"))e.Cancel=true;};
 }
 void Add(string label,Action action){var button=new Button{Text=label,AutoSize=true,Height=32,BackColor=Color.FromArgb(123,200,247),ForeColor=Color.FromArgb(12,25,21),FlatStyle=FlatStyle.Flat,Margin=new Padding(4)};button.Click+=(s,e)=>action();tools.Controls.Add(button);}
 bool Confirm(string text){return MessageBox.Show(this,text,"Quelli del Quasi",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
 void Service(string verb){var name=(string)service.SelectedItem;if((verb=="stop"||verb=="restart")&&!Confirm(name=="QuasiPostgres"?"Il database richiede di fermare anche web e worker. Gli utenti vedranno un’interruzione. Continuare?":"Eseguire "+verb+" su "+name+"?"))return;Run("service "+verb+" "+name);}
 void Open(string target){try{Process.Start(new ProcessStartInfo(target){UseShellExecute=true});}catch(Exception e){Append(e.Message);}}
 void Append(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Append),text);return;}if(output.TextLength>400000)output.Clear();output.AppendText(text+Environment.NewLine);}
 void Run(string args){if(active!=null&&!active.HasExited)return;var script=Path.Combine(root,"app","runtime","admin-control.mjs");if(!File.Exists(script)){Append("Installazione non trovata: "+root);return;}tools.Enabled=false;output.Clear();Append(DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+" · "+args);
  var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"nodejs","node.exe"),"--env-file=\""+Path.Combine(root,"config","app.env")+"\" \""+script+"\" "+args){WorkingDirectory=Path.Combine(root,"app"),UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};
  active=new Process{StartInfo=info,EnableRaisingEvents=true};active.OutputDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};active.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};active.Exited+=(s,e)=>{if(!IsDisposed)BeginInvoke(new Action(()=>{Append("Comando terminato · codice "+active.ExitCode);tools.Enabled=true;}));};try{active.Start();active.BeginOutputReadLine();active.BeginErrorReadLine();}catch(Exception e){Append(e.Message);tools.Enabled=true;}
 }
}
